window.KG_DASH = "<!doctype html>\n<html lang=\"en\">\n<head><script>(()=>{const mk=()=>{const m=new Map();return{getItem:(k)=>m.has(String(k))?m.get(String(k)):null,setItem:(k,v)=>{m.set(String(k),String(v));},removeItem:(k)=>{m.delete(String(k));},clear:()=>{m.clear();},key:(i)=>Array.from(m.keys())[i]??null,get length(){return m.size;}};};for(const n of[\"localStorage\",\"sessionStorage\"]){try{Object.defineProperty(window,n,{value:mk(),configurable:true});}catch(e){}}})();</script>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Lumen focus timer</title>\n    <style>/* Lumen focus timer: one card per job (clock, tasks, today), dark by default. */\n:root { --bg: #120d1c; --card: #1d1630; --line: #352a52; --text: #f1ecff; --mute: #a99cc9; --a: #f472b6; --b: #a78bfa; }\n* { box-sizing: border-box; }\nbody { margin: 0; font: 15px/1.5 system-ui, \"Segoe UI\", sans-serif; background: var(--bg); color: var(--text); }\nbutton { font: inherit; color: inherit; background: #2a2142; border: 1px solid var(--line); border-radius: 10px; padding: 8px 14px; cursor: pointer; }\nbutton.primary { background: linear-gradient(90deg, var(--a), var(--b)); border: 0; color: #160f24; font-weight: 600; }\nbutton.ghost { background: transparent; }\n.bar { display: flex; align-items: center; gap: 14px; padding: 14px 20px; border-bottom: 1px solid var(--line); }\n.brand { font-weight: 700; font-size: 18px; display: flex; align-items: center; gap: 8px; }\n.brand small { color: var(--mute); font-weight: 400; font-size: 13px; }\n.mark { width: 18px; height: 18px; border-radius: 50%; background: conic-gradient(var(--a), var(--b), var(--a)); }\n.sync { margin-inline-start: auto; color: var(--mute); font-size: 13px; }\n.sync.server { color: #86efac; }\n.layout { display: grid; grid-template-columns: 1.1fr 1fr; gap: 18px; padding: 20px; max-width: 1100px; margin: 0 auto; }\n.card { background: var(--card); border: 1px solid var(--line); border-radius: 18px; padding: 20px; }\n.clock { grid-row: span 2; display: flex; flex-direction: column; align-items: center; gap: 14px; }\n.dial { position: relative; display: grid; place-items: center; }\n.mode { display: flex; gap: 6px; }\n.mode button.on { border-color: var(--a); color: var(--a); }\n.ring { width: min(260px, 70vw); transform: rotate(-90deg); }\n.ring circle { fill: none; stroke-width: 10; }\n.ring .track { stroke: var(--line); }\n.ring .fill { stroke: var(--a); stroke-linecap: round; stroke-dasharray: 553; stroke-dashoffset: 0; transition: stroke-dashoffset .4s linear; }\n.time { position: absolute; inset: 0; display: grid; place-items: center; font-size: 52px; font-weight: 700; letter-spacing: 1px; }\n.controls { display: flex; gap: 10px; }\nh2 { margin: 0 0 12px; font-size: 16px; }\n.add { display: flex; gap: 8px; margin-bottom: 12px; }\n.add input { flex: 1; min-width: 0; background: #140f22; border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px; color: var(--text); font: inherit; }\n.list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }\n.list li { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 1px solid var(--line); border-radius: 10px; }\n.list li.done span { text-decoration: line-through; color: var(--mute); }\n.list li .del { margin-inline-start: auto; padding: 2px 8px; }\n.nums { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; text-align: center; }\n.nums b { display: block; font-size: 28px; }\n.nums span { color: var(--mute); font-size: 12px; }\n.week { display: flex; align-items: flex-end; gap: 6px; height: 70px; margin-top: 14px; }\n.week i { flex: 1; background: linear-gradient(var(--a), var(--b)); border-radius: 4px 4px 0 0; min-height: 3px; }\ndialog { background: var(--card); color: var(--text); border: 1px solid var(--line); border-radius: 16px; padding: 22px; width: min(360px, 92vw); }\ndialog label { display: grid; gap: 4px; margin-bottom: 12px; color: var(--mute); }\ndialog label.row { display: flex; align-items: center; gap: 8px; }\ndialog input[type=number] { background: #140f22; border: 1px solid var(--line); border-radius: 8px; padding: 6px 10px; color: var(--text); font: inherit; }\n.actions { display: flex; justify-content: flex-end; gap: 8px; }\n.toast { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); background: #2a2142; border: 1px solid var(--line); padding: 10px 16px; border-radius: 12px; }\n@media (max-width: 760px) { .layout { grid-template-columns: 1fr; padding: 12px; } .clock { grid-row: auto; } .time { font-size: 44px; } }\n@media (prefers-reduced-motion: reduce) { .ring .fill { transition: none; } }\n</style>\n</head>\n<body>\n  <header class=\"bar\">\n    <div class=\"brand\"><span class=\"mark\"></span>Lumen <small>focus timer</small></div>\n    <div class=\"sync\" id=\"sync\" title=\"Where your sessions are saved\">saved on this device</div>\n    <button class=\"ghost\" id=\"b-settings\" type=\"button\">Settings</button>\n  </header>\n\n  <main class=\"layout\">\n    <section class=\"clock card\">\n      <div class=\"mode\" id=\"mode\">\n        <button type=\"button\" data-mode=\"focus\" class=\"on\">Focus</button>\n        <button type=\"button\" data-mode=\"break\">Break</button>\n      </div>\n      <div class=\"dial\">\n        <svg class=\"ring\" viewBox=\"0 0 200 200\" aria-hidden=\"true\">\n          <circle class=\"track\" cx=\"100\" cy=\"100\" r=\"88\"/>\n          <circle class=\"fill\" id=\"ring\" cx=\"100\" cy=\"100\" r=\"88\"/>\n        </svg>\n        <div class=\"time\" id=\"time\">25:00</div>\n      </div>\n      <div class=\"controls\">\n        <button type=\"button\" id=\"b-start\" class=\"primary\">Start</button>\n        <button type=\"button\" id=\"b-pause\">Pause</button>\n        <button type=\"button\" id=\"b-reset\">Reset</button>\n      </div>\n    </section>\n\n    <section class=\"tasks card\">\n      <h2>Tasks</h2>\n      <form id=\"add-form\" class=\"add\">\n        <input id=\"task-input\" placeholder=\"What will you focus on?\" autocomplete=\"off\">\n        <button type=\"submit\" class=\"primary\">Add</button>\n      </form>\n      <ul id=\"task-list\" class=\"list\"></ul>\n    </section>\n\n    <section class=\"stats card\">\n      <h2>Today</h2>\n      <div class=\"nums\">\n        <div><b id=\"st-sessions\">0</b><span>sessions</span></div>\n        <div><b id=\"st-minutes\">0</b><span>focus minutes</span></div>\n        <div><b id=\"st-done\">0</b><span>tasks done</span></div>\n      </div>\n      <div class=\"week\" id=\"week\"></div>\n    </section>\n  </main>\n\n  <dialog id=\"settings\">\n    <form method=\"dialog\">\n      <h2>Settings</h2>\n      <label>Focus length (minutes) <input id=\"set-focus\" type=\"number\" min=\"5\" max=\"90\" value=\"25\"></label>\n      <label>Break length (minutes) <input id=\"set-break\" type=\"number\" min=\"1\" max=\"30\" value=\"5\"></label>\n      <label class=\"row\"><input id=\"set-sound\" type=\"checkbox\" checked> Sound when a session ends</label>\n      <div class=\"actions\"><button value=\"cancel\">Cancel</button><button id=\"b-save\" value=\"save\" class=\"primary\">Save</button></div>\n    </form>\n  </dialog>\n  <div class=\"toast\" id=\"toast\" hidden></div>\n  <script>// Lumen focus timer: the page logic. It counts down a focus or break session, keeps a task list, and saves every\n// finished session. It talks to the Lumen server (server/api.py) when the page is served by it; opened as a plain\n// file it saves in this browser instead, so it works with no server at all.\n(() => {\n  const $ = (s) => document.querySelector(s);\n  const RING = 553;   // the ring's circumference: 2 * pi * 88\n  const state = { mode: \"focus\", left: 25 * 60, total: 25 * 60, timer: null, tasks: [], sessions: [], settings: { focus: 25, brk: 5, sound: true }, server: false };\n\n  // ---- storage: the server when it answers, this browser otherwise\n  const local = {\n    get(k, d) { try { return JSON.parse(localStorage.getItem(\"lumen.\" + k)) ?? d; } catch { return d; } },\n    set(k, v) { try { localStorage.setItem(\"lumen.\" + k, JSON.stringify(v)); } catch { /* private window: keep it in memory */ } },\n  };\n  async function api(path, body) {\n    const r = await fetch(\"/api/\" + path, body ? { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(body) } : {});\n    if (!r.ok) throw new Error(path + \": \" + r.status);\n    return r.json();\n  }\n  async function load() {\n    try { throw new Error(\"tour: the sample day below, no server\"); const d = await api(\"state\"); Object.assign(state, { tasks: d.tasks, sessions: d.sessions, settings: d.settings, server: true }); }\n    catch { const day = (n, h) => new Date(Date.now() - n * 864e5 - h * 36e5).toISOString(); Object.assign(state, { tasks: [{ text: \"Write the release notes\", done: true }, { text: \"Review the storage checks\", done: false }, { text: \"Plan next week\", done: false }], sessions: [day(0, 1), day(0, 2), day(0, 3), day(1, 1), day(1, 2), day(2, 1), day(3, 2), day(3, 3), day(3, 4), day(5, 1), day(6, 2)].map((at) => ({ at, minutes: 25 })) }); }\n    $(\"#sync\").textContent = state.server ? \"saved on the Lumen server\" : \"saved on this device\";\n    $(\"#sync\").classList.toggle(\"server\", state.server);\n    setMode(\"focus\"); renderTasks(); renderStats();\n  }\n  async function save(kind, value) {\n    if (state.server) { try { await api(kind, value); return; } catch { state.server = false; } }\n    local.set(kind, kind === \"sessions\" ? state.sessions : kind === \"tasks\" ? state.tasks : state.settings);\n  }\n\n  // ---- the clock\n  const fmt = (s) => String(Math.floor(s / 60)).padStart(2, \"0\") + \":\" + String(s % 60).padStart(2, \"0\");\n  function draw() { $(\"#time\").textContent = fmt(state.left); $(\"#ring\").style.strokeDashoffset = RING * (1 - state.left / state.total); }\n  function setMode(m) {\n    stop(); state.mode = m; state.total = state.left = (m === \"focus\" ? state.settings.focus : state.settings.brk) * 60;\n    document.querySelectorAll(\"#mode button\").forEach((b) => b.classList.toggle(\"on\", b.dataset.mode === m)); draw();\n  }\n  function start() { if (state.timer) return; state.timer = setInterval(tick, 1000); toast(state.mode === \"focus\" ? \"Focus started\" : \"Break started\"); }\n  function stop() { clearInterval(state.timer); state.timer = null; }\n  function tick() { state.left -= 1; draw(); if (state.left <= 0) finish(); }\n  function finish() {\n    stop();\n    if (state.mode === \"focus\") { const s = { at: new Date().toISOString(), minutes: state.settings.focus }; state.sessions.push(s); save(\"sessions\", s); renderStats(); }\n    if (state.settings.sound) beep();\n    toast(state.mode === \"focus\" ? \"Session saved. Time for a break.\" : \"Break over.\");\n    setMode(state.mode === \"focus\" ? \"break\" : \"focus\");\n  }\n  function beep() { try { const c = new AudioContext(), o = c.createOscillator(); o.connect(c.destination); o.frequency.value = 660; o.start(); o.stop(c.currentTime + 0.25); } catch { /* no audio here */ } }\n\n  // ---- tasks\n  function renderTasks() {\n    const ul = $(\"#task-list\"); ul.innerHTML = \"\";\n    state.tasks.forEach((t, i) => {\n      const li = document.createElement(\"li\"); li.className = t.done ? \"done\" : \"\";\n      li.innerHTML = `<input type=\"checkbox\" ${t.done ? \"checked\" : \"\"} aria-label=\"Done\"><span></span><button class=\"del\" type=\"button\" aria-label=\"Delete\">×</button>`;\n      li.querySelector(\"span\").textContent = t.text;\n      li.querySelector(\"input\").addEventListener(\"change\", (e) => { t.done = e.target.checked; save(\"tasks\", state.tasks); renderTasks(); renderStats(); });\n      li.querySelector(\".del\").addEventListener(\"click\", () => { state.tasks.splice(i, 1); save(\"tasks\", state.tasks); renderTasks(); renderStats(); });\n      ul.appendChild(li);\n    });\n  }\n  $(\"#add-form\").addEventListener(\"submit\", (e) => {\n    e.preventDefault(); const v = $(\"#task-input\").value.trim(); if (!v) return;\n    state.tasks.push({ text: v, done: false }); $(\"#task-input\").value = \"\"; save(\"tasks\", state.tasks); renderTasks();\n  });\n\n  // ---- today and the last seven days\n  function renderStats() {\n    const today = new Date().toISOString().slice(0, 10);\n    const todays = state.sessions.filter((s) => s.at.slice(0, 10) === today);\n    $(\"#st-sessions\").textContent = todays.length;\n    $(\"#st-minutes\").textContent = todays.reduce((a, s) => a + s.minutes, 0);\n    $(\"#st-done\").textContent = state.tasks.filter((t) => t.done).length;\n    const days = [...Array(7)].map((_, i) => { const d = new Date(Date.now() - (6 - i) * 864e5).toISOString().slice(0, 10); return state.sessions.filter((s) => s.at.slice(0, 10) === d).reduce((a, s) => a + s.minutes, 0); });\n    const top = Math.max(25, ...days);\n    $(\"#week\").innerHTML = days.map((m) => `<i style=\"height:${Math.round((m / top) * 100)}%\" title=\"${m} min\"></i>`).join(\"\");\n  }\n\n  // ---- settings\n  $(\"#b-settings\").addEventListener(\"click\", () => { $(\"#set-focus\").value = state.settings.focus; $(\"#set-break\").value = state.settings.brk; $(\"#set-sound\").checked = state.settings.sound; $(\"#settings\").showModal(); });\n  $(\"#settings\").addEventListener(\"close\", () => {\n    if ($(\"#settings\").returnValue !== \"save\") return;\n    state.settings = { focus: Math.min(90, Math.max(5, +$(\"#set-focus\").value || 25)), brk: Math.min(30, Math.max(1, +$(\"#set-break\").value || 5)), sound: $(\"#set-sound\").checked };\n    save(\"settings\", state.settings); setMode(state.mode); toast(\"Settings saved\");\n  });\n\n  function toast(msg) { const t = $(\"#toast\"); t.textContent = msg; t.hidden = false; clearTimeout(toast.h); toast.h = setTimeout(() => (t.hidden = true), 2200); }\n  $(\"#b-start\").addEventListener(\"click\", start);\n  $(\"#b-pause\").addEventListener(\"click\", () => { stop(); toast(\"Paused\"); });\n  $(\"#b-reset\").addEventListener(\"click\", () => setMode(state.mode));\n  document.querySelectorAll(\"#mode button\").forEach((b) => b.addEventListener(\"click\", () => setMode(b.dataset.mode)));\n  load();\n})();\n</script>\n</body>\n</html>\n";
